      expectStatus(patched, [200]);
      expectEcho(input.patchBody, patched.json);
      const removed = await api.send({ method: 'DELETE', path: '/users/{id}', identity: 'default', pathParams: { id: id } });
      expectStatus(removed, [200,204]);
      // 4. the "deleted" resource is still there
      const still = await api.send({ method: 'GET', path: '/users/{id}', identity: 'default', pathParams: { id: id } });
